// One reading, plus a fixture so the notebook works on a plane.
const FIXTURE = { latitude: -10.49, longitude: 170.81, note: 'bundled fixture (2026-07-10)' };

let reading, live = false;
try {
  const res = await fetch('http://api.open-notify.org/iss-now.json');
  if (!res.ok) throw new Error('HTTP ' + res.status);
  const data = await res.json();
  reading = {
    latitude: Number(data.iss_position.latitude),
    longitude: Number(data.iss_position.longitude),
    note: 'live at ' + new Date(data.timestamp * 1000).toISOString(),
  };
  live = true;
} catch (err) {
  console.warn('live fetch failed (' + err.message + ') - using the fixture');
  reading = FIXTURE;
}

console.log('ISS is over', reading.latitude.toFixed(2) + '°,',
  reading.longitude.toFixed(2) + '°', '(' + reading.note + ')');

// dead-reckoning context: one orbit is ~92.9 min, so in 10 minutes it
// travels ~39° of arc - by the time you scroll down it has moved.
console.log('ground speed ~7.66 km/s: it crosses your horizon-to-horizon sky in ~6 minutes');

nb.set('iss_seed', { lat: reading.latitude, lon: reading.longitude, live });
return { ...reading, live };
